// Independent browser capability probe: no Blazor, no application code or user data.
const {webkit}=require('playwright'),http=require('node:http'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
(async()=>{
 const report={};const html='<h1>Offline probe</h1><script>navigator.serviceWorker.register("/sw.js")</script>';
 const sw="self.addEventListener('install',e=>e.waitUntil(caches.open('probe').then(c=>c.add('/')).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request))));";
 const server=http.createServer((q,r)=>{r.writeHead(200,{'Content-Type':q.url==='/sw.js'?'text/javascript':'text/html','Cache-Control':'no-store'});r.end(q.url==='/sw.js'?sw:html)});
 await new Promise(r=>server.listen(0,'127.0.0.1',r));const base='http://127.0.0.1:'+server.address().port+'/';
 const profile=fs.mkdtempSync(path.join(os.tmpdir(),'offline-probe-'));let context;
 try{context=await webkit.launchPersistentContext(profile,{headless:true});let page=await context.newPage();await page.goto(base);await page.evaluate(async()=>{await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(r=>navigator.serviceWorker.addEventListener('controllerchange',r,{once:true}))});await context.setOffline(true);await page.reload();await page.getByRole('heading',{name:'Offline probe'}).waitFor();report.sameSessionOffline=true;await context.close();context=await webkit.launchPersistentContext(profile,{headless:true});await context.setOffline(true);page=await context.newPage();try{await page.goto(base);await page.getByRole('heading',{name:'Offline probe'}).waitFor();report.coldOffline=true}catch(e){report.coldOffline=false;report.failure=e.message}}catch(error){report.sameSessionOffline=false;report.failure=error.message}finally{if(context)await context.close();await new Promise(r=>server.close(r));fs.rmSync(profile,{recursive:true,force:true});fs.mkdirSync(process.env.PWA_REPORT_DIR,{recursive:true});fs.writeFileSync(path.join(process.env.PWA_REPORT_DIR,'webkit-capability.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report))}
})().catch(e=>{console.error(e);process.exitCode=1});
